#!/usr/bin/env bash
# Render the Homebrew formula for one release.
#
#   .github/homebrew/formula.sh v0.1.1 <dir-with-.sha256-files> > nosqlsync.rb
#
# The .sha256 files are the ones the release workflow attaches to each GitHub
# Release, so the formula always points at exactly the binaries that shipped.
set -euo pipefail

tag="$1"
sums="$2"

base="https://github.com/NoSQLSync/nosqlsync/releases/download/${tag}"

sha() {
  local file="${sums}/nosqlsync-${tag}-$1.tar.gz.sha256"
  [ -f "$file" ] || { echo "missing checksum: $file" >&2; exit 1; }
  cut -d ' ' -f 1 "$file"
}

asset() {
  printf '      url "%s/nosqlsync-%s-%s.tar.gz"\n      sha256 "%s"\n' "$base" "$tag" "$1" "$(sha "$1")"
}

cat <<EOF
# Generated by .github/homebrew/formula.sh in NoSQLSync/nosqlsync. Do not edit
# by hand: each release regenerates it.
class Nosqlsync < Formula
  desc "Migrate MongoDB to PostgreSQL with a schema you'd actually design"
  homepage "https://github.com/NoSQLSync/nosqlsync"
  license any_of: ["MIT", "Apache-2.0"]

  on_macos do
    on_arm do
$(asset aarch64-apple-darwin)
    end
    on_intel do
$(asset x86_64-apple-darwin)
    end
  end

  on_linux do
    on_arm do
$(asset aarch64-unknown-linux-gnu)
    end
    on_intel do
$(asset x86_64-unknown-linux-gnu)
    end
  end

  def install
    bin.install "nosqlsync"
  end

  test do
    assert_match "nosqlsync #{version}", shell_output("#{bin}/nosqlsync --version")

    (testpath/"orders.json").write <<~JSON
      [{"_id": {"\$oid": "507f1f77bcf86cd799439011"}, "address": {"city": "Oslo"}, "items": [{"sku": "a", "qty": 1}]}]
    JSON
    output = shell_output("#{bin}/nosqlsync analyze --source #{testpath}/orders.json")
    assert_match "address_city", output
    assert_match "child table orders_items", output
  end
end
EOF
